@Controller('orders')
@UseGuards(AuthGuard('jwt'), RolesGuard)
export class OrdersController {
  constructor(private readonly ordersService: OrdersService) {}

  @Get('history')
  async getHistory(@Req() req: any) {
    // Tadi kita set di JwtStrategy pake key 'userId'
    const userId = req.user.userId;
    return this.ordersService.getPurchaseHistory(userId);
  }

  @Get('history/:id')
  async getDetail(
    @Param('id', ParseIntPipe) id: number, // Pake ParseIntPipe biar otomatis convert string ke number
    @Req() req: any,
  ) {
    // Ambil userId dari payload JWT (yang tadi kita set di JwtStrategy)
    const userId = req.user.userId;

    const orderDetail = await this.ordersService.getOrderDetail(id, userId);

    return {
      success: true,
      message: 'Detail pesanan berhasil diambil',
      data: orderDetail,
    };
  }
}

// src/orders/orders.service.ts
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class OrdersService {
  constructor(private prisma: PrismaService) {}

  async getPurchaseHistory(userId: number) {
    const orders = await this.prisma.orders.findMany({
      where: { userId: userId },
      include: {
        orderItems: {
          select: {
            itemName: true,
            itemType: true,
            itemId: true,
            // totalPrice: true, // Saran gue ini tetep di-include buat FE
          },
        },
        payments: {
          select: {
            createdAt: true,
          },
          orderBy: { createdAt: 'desc' },
          take: 1,
        },
      },
      orderBy: { createdAt: 'desc' },
    });

    // 1. Validasi jika data kosong
    if (!orders || orders.length === 0) {
      throw new NotFoundException('Belum ada riwayat pembelian');
    }

    // 2. Mapping data
    return orders.map((order) => ({
      id: order.id,
      date: order.createdAt,
      status: order.orderStatus,
      paymentStatus: order.paymentStatus,
      grandTotal: Number(order.grandTotal), // Pastikan diconvert ke Number
      paymentMethod: order.paymentMethod,
      items: order.orderItems.map((item) => ({
        ...item,
        // totalPrice: Number(item.totalPrice)
      })),
      paymentInfo: order.payments[0] || null,
    }));
  }

  // src/orders/orders.service.ts

  async getOrderDetail(orderId: number, userId: number) {
    const order = await this.prisma.orders.findFirst({
      where: {
        id: orderId,
        userId: userId,
      },
      include: {
        orderItems: true,
        payments: {
          orderBy: { createdAt: 'desc' },
          take: 1,
        },
      },
    });

    if (!order) throw new NotFoundException('Pesanan tidak ditemukan');

    const lastPayment = order.payments[0] || null;

    // Logic instruksi bayar
    const paymentInstructions = {
      method: order.paymentMethod,
      accountName: 'PT Pasti Lolos Indonesia',
      accountNumber:
        order.paymentMethod === 'BCA' ? '1234567890' : '081234567890',
      notes: `Mohon transfer tepat sebesar Rp ${Number(order.grandTotal).toLocaleString('id-ID')}`,
    };

    return {
      orderId: order.id,
      // AMBIL KODE TRANSAKSI DARI TABEL PAYMENT
      transactionCode: lastPayment?.transactionId || '-',
      status: order.orderStatus,
      paymentStatus: order.paymentStatus,
      paymentMethod: order.paymentMethod,
      grandTotal: Number(order.grandTotal),
      discount: Number(order.discountAmount),
      totalAmount: Number(order.totalAmount),
      createdAt: order.createdAt,

      paymentInfo: lastPayment
        ? {
            paymentDate: lastPayment.createdAt,
            paymentMethod: order.paymentMethod,
            amountPaid: Number(lastPayment.amount),
            receiptUrl: lastPayment.receiptUrl,
            status: lastPayment.paymentStatus,
            transactionId: lastPayment.transactionId, // ID Transaksi dari Payment
          }
        : null,

      items: order.orderItems.map((item) => ({
        ...item,
        pricePerItem: Number(item.pricePerItem),
        totalPrice: Number(item.totalPrice),
        metadataJson:
          typeof item.metadataJson === 'string'
            ? JSON.parse(item.metadataJson)
            : item.metadataJson,
      })),

      instructions:
        order.orderStatus === 'pending' ? paymentInstructions : null,
    };
  }
}

import {
  Controller,
  Post,
  Get,
  Query,
  ParseIntPipe,
  Body,
  UseGuards,
  Req,
  UseInterceptors,
  UploadedFile,
  Param,
  Patch,
  BadRequestException,
  ParseFilePipe,
  MaxFileSizeValidator,
  FileTypeValidator,
} from '@nestjs/common';
import { PaymentsService } from './payments.service';
import { AuthGuard } from '@nestjs/passport';
import { FileInterceptor } from '@nestjs/platform-express';
import { RolesGuard } from 'src/auth/guards/roles.guard';
import { Roles } from '../common/decorators/roles.decorators';
import { CheckVoucherDto } from './dto/coupon-check.dto';

@Controller('payments')
@UseGuards(AuthGuard('jwt'), RolesGuard)
export class PaymentsController {
  constructor(private readonly paymentsService: PaymentsService) {}

  @Post('apply-coupon')
  async applyVoucher(@Body() dto: CheckVoucherDto) {
    // Memproses pengecekan voucher via body request
    return await this.paymentsService.validateVoucher(
      dto.couponCode,
      dto.examId,
    );
  }
  // URL KHUSUS CHECKOUT EXAM
  @Post('checkout/exam')
  @UseInterceptors(FileInterceptor('file'))
  async checkoutExam(
    @UploadedFile(
      new ParseFilePipe({
        validators: [
          new MaxFileSizeValidator({ maxSize: 2 * 1024 * 1024 }), // Batas 2MB
          new FileTypeValidator({ fileType: '.(png|jpeg|jpg)' }), // Cuma gambar[cite: 6]
        ],
      }),
    )
    file: Express.Multer.File,
    @Body()
    body: { examId: string; paymentMethod: string; discountCode?: string },
    @Req() req: any,
  ) {
    return this.paymentsService.processExamManualPayment(
      +body.examId,
      req.user.userId,
      body.paymentMethod,
      file,
      body.discountCode,
    );
  }

  @Patch('verify/:orderId')
  @Roles('3') // Cuma Admin yang bisa approve[cite: 6]
  async verify(@Param('orderId') orderId: string) {
    return this.paymentsService.approveManualPayment(+orderId);
  }

  @Patch('approve/:orderId') // atau @Post sesuai route lo
  @Roles('3') // Cuma Admin yang bisa approve[cite: 6]
  async approvePayment(@Param('orderId') orderId: string) {
    // Gunakan Number(orderId) atau +orderId untuk konversi string ke number
    return this.paymentsService.approveManualPayment(Number(orderId));
  }

  @Patch('verify-bulk')
  @Roles('3') // Admin Only[cite: 9]
  async verifyBulk(@Body('orderIds') orderIds: number[]) {
    return this.paymentsService.approveBulkPayments(orderIds);
  }

  @Post('upload-proof')
  @UseInterceptors(
    FileInterceptor('file', {
      limits: {
        fileSize: 2 * 1024 * 1024, // Batas 2MB[cite: 6]
      },
      fileFilter: (req, file, callback) => {
        // Cuma terima gambar[cite: 6]
        if (!file.mimetype.match(/\/(jpg|jpeg|png)$/)) {
          return callback(
            new BadRequestException('Cuma boleh upload JPG, JPEG, atau PNG!'),
            false,
          );
        }
        callback(null, true);
      },
    }),
  )
  async uploadProof(
    @UploadedFile() file: Express.Multer.File,
    @Body('orderId') orderId: string,
  ) {
    if (!file) throw new BadRequestException('File-nya mana?');

    // Lanjut proses upload ke Cloudinary...[cite: 6, 9]
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import * as PDFDocument from 'pdfkit';
import { Response } from 'express';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class CertificatesService {
  constructor(private prisma: PrismaService) {}

  async generateExamCertificate(userExamId: number, res: Response) {
    const attempt = await this.prisma.userExams.findUnique({
      where: { id: userExamId },
      include: {
        user: true,
        exam: true,
      },
    });

    if (!attempt || attempt.status !== 'submitted') {
      throw new NotFoundException(
        'Data ujian tidak ditemukan atau belum selesai',
      );
    }

    const doc = new PDFDocument({ layout: 'landscape', size: 'A4' });

    // Set Header Response
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader(
      'Content-Disposition',
      `attachment; filename=Sertifikat-${attempt.id}.pdf`,
    );

    doc.pipe(res);

    // --- DESAIN SERTIFIKAT ---
    // Frame luar
    doc.rect(20, 20, doc.page.width - 40, doc.page.height - 40).stroke();

    // Konten
    doc
      .fontSize(40)
      .text('SERTIFIKAT KELULUSAN', { align: 'center' })
      .moveDown();
    doc
      .fontSize(20)
      .text('Diberikan kepada:', { align: 'center' })
      .moveDown(0.5);

    // Nama User
    doc
      .fontSize(35)
      .font('Helvetica-Bold')
      .text(attempt.user.firstName + ' ' + (attempt.user.lastName || ''), {
        align: 'center',
      })
      .moveDown();

    doc
      .fontSize(18)
      .font('Helvetica')
      .text(`Atas keberhasilannya menyelesaikan ujian:`, { align: 'center' });
    doc
      .fontSize(22)
      .font('Helvetica-Bold')
      .text(`${attempt.exam.examName}`, { align: 'center' })
      .moveDown();

    doc
      .fontSize(16)
      .font('Helvetica')
      .text(`Skor Akhir: ${attempt.score}`, { align: 'center' })
      .moveDown(2);

    // Footer
    doc
      .fontSize(12)
      .text(`Diterbitkan pada: ${new Date().toLocaleDateString('id-ID')}`, {
        align: 'right',
      });
    doc.text('Pasti Lolos Indonesia', { align: 'right' });

    doc.end();
  }
}

import {
  Controller,
  Query,
  Get,
  UseGuards,
  Req,
  Param,
  ParseIntPipe,
